from pathlib import Path
import base64, json
R = Path(__file__).resolve().parents[2]
O = R / 'renders/secretgarden_reseau_v1'
m = json.loads((O / 'manifest.json').read_text())


def uri(p):
    return 'data:image/png;base64,' + base64.b64encode(p.read_bytes()).decode()


data = {e['id']: {**e, 'images': {n: uri(O / e['id'] / (n + '.png')) for n in e['layers']},
                  'schema': uri(O / e['id'] / 'schema.png')} for e in m['rooms']}
h = '''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jardin secret · réseau connectable</title><style>*{box-sizing:border-box}body{margin:0;background:#1d3320;color:#eef4da;font:16px system-ui}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#cfdcc0;line-height:1.6}.tag{font-size:12px;letter-spacing:2px;color:#b8d489}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:12px;border:1px solid #6f9151;border-radius:6px;background:#33482a;color:#f4f9e8}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}canvas{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#101a10}aside{background:#24351f;padding:18px;border-radius:8px}label{display:block;margin:15px 0;font-size:14px}a{color:#d7e8b8}small{color:#b3c49b}footer{border-top:1px solid #435c36}@media(max-width:780px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">JARDIN SECRET / RÉSEAU STYLE LEDIAN</div><h1>Six pièces connectables · 16 accès</h1><p>Clairières, couloirs et carrefours générés d’après secretgarden.png, découpés en calques alignés. Raccords d’herbe native, ports de 64px. Jonction en T prévue au prochain lot.</p></header><main><div class="toolbar"><select id="room"></select><button id="plan">Voir schéma des accès</button><button id="reference">Voir référence native</button><button id="export">Exporter PNG affiché</button></div><div class="layout"><section><canvas id="view" width="512" height="512"></canvas><p id="status"></p></section><aside><b>Calques alignés · 512 × 512</b><div id="layers"></div><small>Les raccords d’herbe sont indépendants. Végétation et rochers : partitions visibles, pas des volumes reconstruits derrière les autres calques. La bande commune garantit le sol au passage, pas l’emboîtement de toute la silhouette végétale.</small></aside></div></main><footer><p>Source : secretgarden.png (commit utilisateur). Architectures générées guidées, pas des cartes natives originales. Le patch des raccords provient directement des pixels sources.</p><small>16 ports de 64px : bande de 24px opaque vérifiée. Ni collisions, ni transitions PMDO, ni test de navigation. Rendus statiques, sans animation de décor.</small></footer><script>const DATA=__DATA__,REF=__REF__,c=document.getElementById('view'),ctx=c.getContext('2d'),select=document.getElementById('room');let entry,images={},visible={},schema=false,reference=false;function image(src){let im=new Image();im.src=src;return im}const ref=image(REF);function download(src,name){let a=document.createElement('a');a.href=src;a.download=name;a.click()}for(const [id,e]of Object.entries(DATA)){let o=document.createElement('option');o.value=id;o.textContent=e.title;select.append(o)}select.value='salle_carrefour';function setup(){entry=DATA[select.value];images={};visible={};const root=document.getElementById('layers');root.innerHTML='';for(const n of entry.layers){images[n]=image(entry.images[n]);visible[n]=true;const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=visible[n];ch.onchange=()=>visible[n]=ch.checked;a.href=entry.images[n];a.download=entry.id+'_'+n+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(n.replace(/^\\d+_/,'').replaceAll('_',' ')),a);root.append(l)}images.schema=image(entry.schema);document.getElementById('status').textContent=entry.title+' · Accès : '+entry.ports.map(p=>p.direction).join(' / ')+' · largeur de raccord 64px'}select.onchange=setup;document.getElementById('plan').onclick=e=>{schema=!schema;reference=false;e.target.textContent=schema?'Voir rendu':'Voir schéma des accès'};document.getElementById('reference').onclick=e=>{reference=!reference;e.target.textContent=reference?'Revenir à la variante':'Voir référence native'};document.getElementById('export').onclick=()=>download(c.toDataURL(),reference?'secretgarden_reference.png':entry.id+(schema?'_schema':'')+'.png');function draw(im){if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}function render(){const w=reference?408:512,h=reference?408:512;if(c.width!==w||c.height!==h){c.width=w;c.height=h}ctx.clearRect(0,0,c.width,c.height);if(reference)draw(ref);else if(schema)draw(images.schema);else for(const n of entry.layers)if(visible[n])draw(images[n]);requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R / 'apercu_jardin_secret_reseau_v1.html').write_text(
    h.replace('__DATA__', json.dumps(data)).replace('__REF__', json.dumps(uri(R / 'secretgarden.png'))),
    encoding='utf8')
print('gallery written')
